package com.muxigame.city;
import java.util.*;import net.minecraft.core.*;import net.minecraft.core.component.DataComponents;import net.minecraft.gametest.framework.*;import net.minecraft.nbt.*;import net.minecraft.world.SimpleContainer;import net.minecraft.world.item.*;import net.minecraft.world.item.component.CustomData;import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false) public final class CityTestsLaw {
 static ItemStack stolen(){var v=new ItemStack(Items.BREAD,3);var tag=new CompoundTag();var own=new CompoundTag();own.putUUID("Incident",UUID.randomUUID());own.putString("CityName","原属城市");tag.put("cpn_stolen",own);v.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));return v;}
 @GameTest(template="empty") public static void rulesAndPersistence(GameTestHelper h){var law=new CityLaw();UUID id=UUID.randomUUID();var r=law.record(id);r.rules.addProperty("security",73);r.rules.addProperty("guardLoss",5);r.revision=9;r.journal.add("失窃装备 · 75→73");var copy=CityLaw.load(law.save(new CompoundTag(),h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(copy.records.get(id).rules.get("security").getAsInt()==73&&copy.records.get(id).revision==9&&copy.records.get(id).journal.size()==1,"Rules, security, version and audit persist");var bad=CityLaw.defaults();bad.addProperty("guardLoss",-1);boolean rejected=false;try{CityLaw.validate(bad);}catch(Exception e){rejected=true;}h.assertTrue(rejected,"Invalid loss rejected");h.succeed();}
 @GameTest(template="empty") public static void stolenTradePreservesAndRollsBack(GameTestHelper h){var e=new CityEconomy();e.adjust("person",100,0,"test");e.adjust("shop",100,0,"test");var bag=new SimpleContainer(2);var stock=new SimpleContainer(2);var source=stolen();bag.setItem(0,source.copy());var moved=e.exchangeTrade(stock,bag,2,"person","shop","minecraft:bread",false,5,1,"test");h.assertTrue(bag.getItem(0).getCount()==2&&ItemStack.isSameItemSameComponents(moved,source)&&ItemStack.isSameItemSameComponents(stock.getItem(0),source),"Sale preserves stolen components");h.assertTrue(e.balance("person")==105&&e.balance("shop")==95,"Sale conserves funds");e.exchangeTrade(stock,bag,2,"person","shop","minecraft:bread",true,5,2,"test");h.assertTrue(bag.getItem(0).getCount()==3&&stock.getItem(0).isEmpty(),"Repurchase cannot launder stolen marker");stock.setItem(0,new ItemStack(Items.STONE,64));stock.setItem(1,new ItemStack(Items.STONE,64));boolean fail=false;try{e.exchangeTrade(stock,bag,2,"person","shop","minecraft:bread",false,5,3,"test");}catch(Exception ex){fail=true;}h.assertTrue(fail&&bag.getItem(0).getCount()==3&&e.balance("person")==100,"Full destination rolls back items and money");h.succeed();}
 @GameTest(template="empty") public static void customItemsRemainProtected(GameTestHelper h){var stack=stolen();h.assertTrue(CityLaw.tradeGood(stack,Items.BREAD),"Ownership-only marker supported");stack.set(DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("私人定制"));h.assertTrue(!CityLaw.tradeGood(stack,Items.BREAD),"Named items cannot be stripped by trade");h.succeed();}
 @GameTest(template="empty") public static void stolenCallbacksWaitForInterrogationWithoutMutatingAnything(GameTestHelper h){var player=h.makeMockServerPlayerInLevel();var pos=h.absolutePos(new BlockPos(1,2,1));player.setPos(pos.getX(),pos.getY(),pos.getZ());var cities=CityData.get(player.server);var c=cities.create(player.getUUID(),"赃物兼容验证",h.getLevel().dimension().location().toString(),CityBounds.between(pos,pos.offset(2,2,2)));var law=CityLaw.get(player.server);try{var record=law.record(c.id);record.rules.addProperty("security",73);record.revision=19;record.journal.add("旧存档记录");var item=stolen();var tag=CityLaw.stolen(item);tag.putUUID("CityId",c.id);String before=law.save(new CompoundTag(),h.getLevel().registryAccess()).toString(),marker=tag.toString();for(int i=0;i<3;i++)for(String action:List.of("use","sale","guard"))CityLaw.penalize(player,tag,action,player);h.assertTrue(before.equals(law.save(new CompoundTag(),h.getLevel().registryAccess()).toString())&&tag.toString().equals(marker)&&CityLaw.security(player.server,c.id)==73,"Legacy valid callbacks preserve security, rules, revision, journal and origin until interrogation is implemented");var loaded=CityLaw.load(law.save(new CompoundTag(),h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(loaded.records.get(c.id).revision==19&&loaded.records.get(c.id).rules.get("saleLoss").getAsInt()==4,"Old configured values still serialize unchanged; no schema/API break");CityLaw.penalize(null,null,null,null);h.assertTrue(ItemStack.isSameItemSameComponents(item,stolenCopy(item)),"No callback strips original stolen item components");}finally{cities.cities.remove(c.id);law.records.remove(c.id);}h.succeed();}
 static ItemStack stolenCopy(ItemStack item){return item.copy();}
}
